import base64
import hashlib
import os
import secrets
import urllib.parse
from dataclasses import dataclass
from typing import Any, Dict, Optional

import requests


@dataclass
class PKCEAuthResult:
    authorization_url: str
    code_verifier: str
    state: str


class Auth0PKCEClient:
    """
    PKCE login flow for public clients using Auth0's OIDC /authorize and /oauth/token endpoints.
    """

    def __init__(
        self,
        domain: Optional[str] = None,
        client_id: Optional[str] = None,
        audience: Optional[str] = None,
        scope: str = "openid profile email",
        redirect_uri: Optional[str] = None,
    ) -> None:
        self.domain = domain or os.environ.get("AUTH0_DOMAIN")
        self.client_id = client_id or os.environ.get("AUTH0_CLIENT_ID")
        self.audience = audience or os.environ.get("AUTH0_AUDIENCE")
        self.scope = scope
        self.redirect_uri = redirect_uri or os.environ.get("AUTH0_REDIRECT_URI")

        if not self.domain:
            raise ValueError("Missing AUTH0_DOMAIN")
        if not self.client_id:
            raise ValueError("Missing AUTH0_CLIENT_ID")
        if not self.redirect_uri:
            raise ValueError("Missing AUTH0_REDIRECT_URI")

        self.issuer_base = self._normalize_domain(self.domain)
        self.authorize_endpoint = f"https://{self.issuer_base}/authorize"
        self.token_endpoint = f"https://{self.issuer_base}/oauth/token"
        self.userinfo_endpoint = f"https://{self.issuer_base}/userinfo"

    @staticmethod
    def _normalize_domain(domain: str) -> str:
        domain = domain.strip()
        return domain[8:] if domain.startswith("https://") else domain[7:] if domain.startswith("http://") else domain

    @staticmethod
    def _base64url_encode(raw: bytes) -> str:
        return base64.urlsafe_b64encode(raw).rstrip(b"=").decode("ascii")

    @classmethod
    def _generate_code_verifier(cls) -> str:
        return cls._base64url_encode(secrets.token_bytes(32))

    @classmethod
    def _code_challenge_s256(cls, verifier: str) -> str:
        digest = hashlib.sha256(verifier.encode("ascii")).digest()
        return cls._base64url_encode(digest)

    @staticmethod
    def _generate_state() -> str:
        return secrets.token_urlsafe(32)

    def build_authorization_url(self) -> PKCEAuthResult:
        code_verifier = self._generate_code_verifier()
        code_challenge = self._code_challenge_s256(code_verifier)
        state = self._generate_state()

        params = {
            "response_type": "code",
            "client_id": self.client_id,
            "redirect_uri": self.redirect_uri,
            "scope": self.scope,
            "state": state,
            "code_challenge": code_challenge,
            "code_challenge_method": "S256",
        }
        if self.audience:
            params["audience"] = self.audience

        authorization_url = f"{self.authorize_endpoint}?{urllib.parse.urlencode(params)}"
        return PKCEAuthResult(
            authorization_url=authorization_url,
            code_verifier=code_verifier,
            state=state,
        )

    def exchange_code_for_tokens(self, code: str, code_verifier: str) -> Dict[str, Any]:
        payload = {
            "grant_type": "authorization_code",
            "client_id": self.client_id,
            "code": code,
            "code_verifier": code_verifier,
            "redirect_uri": self.redirect_uri,
        }

        response = requests.post(
            self.token_endpoint,
            json=payload,
            headers={"Content-Type": "application/json"},
            timeout=30,
        )
        response.raise_for_status()
        return response.json()

    def get_userinfo(self, access_token: str) -> Dict[str, Any]:
        response = requests.get(
            self.userinfo_endpoint,
            headers={"Authorization": f"Bearer {access_token}"},
            timeout=30,
        )
        response.raise_for_status()
        return response.json()


def start_pkce_login_flow(
    domain: Optional[str] = None,
    client_id: Optional[str] = None,
    redirect_uri: Optional[str] = None,
    audience: Optional[str] = None,
    scope: str = "openid profile email",
) -> PKCEAuthResult:
    client = Auth0PKCEClient(
        domain=domain,
        client_id=client_id,
        audience=audience,
        scope=scope,
        redirect_uri=redirect_uri,
    )
    return client.build_authorization_url()


def complete_pkce_login_flow(
    code: str,
    code_verifier: str,
    domain: Optional[str] = None,
    client_id: Optional[str] = None,
    redirect_uri: Optional[str] = None,
    audience: Optional[str] = None,
    scope: str = "openid profile email",
) -> Dict[str, Any]:
    client = Auth0PKCEClient(
        domain=domain,
        client_id=client_id,
        audience=audience,
        scope=scope,
        redirect_uri=redirect_uri,
    )
    token_response = client.exchange_code_for_tokens(code, code_verifier)
    userinfo = client.get_userinfo(token_response["access_token"])
    return {
        "tokens": token_response,
        "userinfo": userinfo,
    }
